Account.ready.then(user=>{
 const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let bank=[],pending=null,busy=false;
 function render(){const term=$('case-search').value.trim().toLowerCase();const rows=bank.filter(c=>(c.id+' '+c.title+' '+c.questions.map(q=>q.subject+' '+q.topic).join(' ')).toLowerCase().includes(term));$('case-list').innerHTML=rows.map(c=>`<section class="case-card"><h2>${esc(c.id)} — ${esc(c.title)}</h2><p><strong>${esc(c.status)}</strong> · ${c.questions.length} active questions · ${c.total_points} points · ${c.released?'Available to learners':'Not available to learners'}${c.archived?' · '+c.archived+' archived':''}</p>${c.warnings.map(w=>`<p class="warning">${esc(w)}</p>`).join('')}<ol>${c.questions.map(q=>`<li><a href="/admin?workflow=scenario&question=${encodeURIComponent(q.id)}">${esc(c.id)}${String.fromCharCode(64+q.case_order)} · ${esc(q.display_code||q.id)}</a> ${esc(q.text)} <small>(${esc(q.status)} · ${q.maximum} points)</small></li>`).join('')}</ol><a href="/admin?workflow=scenario&case=${encodeURIComponent(c.id)}">Edit shared scenario</a><a href="/admin?workflow=scenario&case=${encodeURIComponent(c.id)}&new=1">Add linked question</a><a href="/?set=1&case=${encodeURIComponent(c.id)}&mode=reviewer">Preview case</a><div><button class="primary" data-id="${esc(c.id)}" data-status="Published" ${!c.can_publish||c.released?'disabled':''}>Publish whole case</button><button class="secondary" data-id="${esc(c.id)}" data-status="Draft" ${!c.questions.length||c.status==='Draft'?'disabled':''}>Return whole case to Draft</button></div></section>`).join('')||'<p>No cases match. Create a shared case in the detailed editor, then link questions using its Case ID and order.</p>';
 document.querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>{const c=bank.find(c=>c.id===b.dataset.id);pending={id:c.id,case_revision:c.revision,revisions:Object.fromEntries(c.questions.map(q=>[q.id,q.revision])),status:b.dataset.status,account_id:user.id};$('publication-title').textContent=pending.status==='Published'?'Publish '+c.id+'?':'Return '+c.id+' to Draft?';$('publication-summary').textContent=c.questions.length+' questions · '+c.total_points+' points. '+(pending.status==='Published'?'All listed questions will become available to learners.':'All listed questions will be removed from new learner sessions.');$('publication-questions').innerHTML=c.questions.map(q=>`<li>${esc(q.id)}: ${esc(q.status)} → ${pending.status}</li>`).join('');$('publication-error').textContent='';$('publication-dialog').showModal()});
 }
 async function load(){bank=await Account.request('/api/admin/case-overview');render();$('overview-status').textContent=bank.length+' cases · '+bank.filter(c=>c.released).length+' published in full.';}
 $('case-search').oninput=render;$('refresh-cases').onclick=()=>load().catch(e=>$('overview-status').textContent=e.message);
 $('cancel-publication').onclick=()=>{if(!busy)$('publication-dialog').close()};$('publication-dialog').addEventListener('cancel',e=>{if(busy)e.preventDefault()});
 $('confirm-publication').onclick=async()=>{if(busy||!pending)return;busy=true;$('confirm-publication').disabled=true;$('cancel-publication').disabled=true;try{const r=await Account.request('/api/admin/case-publication',pending);$('publication-dialog').close();await load();$('overview-status').textContent=r.updated+' questions updated together. Backup verified.';}catch(e){$('publication-error').textContent=e.message+' Refresh Case scenarios before trying again.';}finally{busy=false;$('confirm-publication').disabled=false;$('cancel-publication').disabled=false;}};
 load().catch(e=>$('overview-status').textContent=e.message);
}).catch(()=>{});
